+            BytesRef scratch = new BytesRef();
+            for (long i = 0; i < positions; i++) {
+                BytesRef key1 = this.tsidHashes.get(intervalHash.getKey1(i), scratch);
+                tsidHashesBuilder.appendBytesRef(key1);
